::: {layout-ncol="2"}

::: {#fcf5db68 .cell execution_count=2}
``` {.python .cell-code}
person = graph.get_id_from_label
graph.layout_bipartite(
    nodes=[person(p) for p in ["Ana", "Ben", "Cruz"]],
    align="horizontal", aspect_ratio=0.5,
)
